import {defaultDetails,cabinSurface} from './kit.js?v=expanded-1';
import {uid,CATALOG,MAX_STICKERS,build,normalize,importLegacy,palette,constrain as constrainWorkshopSticker} from './model.js?v=flight-1';
import {renderCraft as drawWorkshopCraft} from './render.js?v=flight-1';
const $=s=>document.querySelector(s);
const KEY='astra.hangar.workshop.v2',DRAFT_KEY='astra.hangar.workshop.draft.v2',LEGACY_KEY='astra.hangar.concept.v1';
const clone=x=>JSON.parse(JSON.stringify(x));
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PARTS=[['cabin','Cabin','M5 19V8l7-5 7 5v11M8 9h8v5H8z'],['body','Body','M4 8l4-4h8l4 4v10l-4 3H8l-4-3zM4 12h16'],['legs','Legs','M8 4L3 20M16 4l5 16M1 21h6M17 21h6M7 10l-4 6M17 10l4 6'],['engine','Engine','M8 3h8v6l4 10H4L8 9zM8 22h8'],['palette','Paint','M12 3a9 9 0 1 0 0 18h2a2 2 0 0 0 0-4 2 2 0 0 1 0-4h3a4 4 0 0 0 4-4c0-4-5-6-9-6zM7 9h1M10 6h1M15 7h1M6 14h1'],['flame','Flame','M12 2c2 7 7 9 7 14a7 7 0 0 1-14 0c0-3 2-6 4-8 0 4 2 5 3 5 2-3 1-7 0-11z'],['stickers','Stickers','M12 2l3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1z'],['builds','Builds','M5 10l7-7 7 7M7 9v12h10V9M10 21v-7h4v7']];
const INFO={cabin:['Cabin','Start with the personality.'],body:['Main body','The heart of your build.'],legs:['Landing gear','Different looks. The same foot contacts.'],engine:['Engine appearance','All cosmetic. No change to thrust or fuel.'],palette:['Coordinated paint','One click. A whole new character.'],flame:['Flame','A little flair behind you.'],stickers:['Stickers','Add one, then drag it on the body.'],builds:['Starting builds','Remix a complete design. Keep making it yours.']};
let collection={crafts:[build('explorer'),build('visitor'),build('breakfast')],selected:null},storageIssue='',legacyImported=false;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.crafts?.length){collection={crafts:saved.crafts.map(normalize),selected:saved.selected}}else{const old=JSON.parse(localStorage.getItem(LEGACY_KEY));if(old?.crafts?.length){collection={crafts:old.crafts.map(importLegacy),selected:old.selected};legacyImported=true}}}catch{storageIssue='Storage unavailable. Save may not persist on this browser.'}
collection.selected=collection.crafts.some(c=>c.id===collection.selected)?collection.selected:collection.crafts[0].id;
try{if(!localStorage.getItem(KEY))localStorage.setItem(KEY,JSON.stringify(collection))}catch{storageIssue='Local saving unavailable. Keep this tab open while building.'}
const requestedCraft=new URL(location.href).searchParams.get('craft');
let craft=clone(collection.crafts.find(c=>c.id===requestedCraft)||collection.crafts.find(c=>c.id===collection.selected)),baseline=JSON.stringify(craft),category='cabin',filter='All',adjusting=false,pins=new Set(),undo=[],redo=[],selectedSticker=-1,flightScale=false,dialog=$('#dialog');
const dirty=()=>JSON.stringify(craft)!==baseline;
function say(message){$('#message').textContent=message}
function remember(){if(!dirty()){clearDraft();return true}try{localStorage.setItem(DRAFT_KEY,JSON.stringify({craft,baseline}));return true}catch{say('Draft recovery unavailable. Save before closing.');return false}}
function store(next){try{localStorage.setItem(KEY,JSON.stringify(next));collection=next;return true}catch{say('Could not save. Your draft is still here.');return false}}
function clearDraft(){try{localStorage.removeItem(DRAFT_KEY)}catch{}}
function mutate(fn,message){const before=clone(craft);fn();if(JSON.stringify(before)===JSON.stringify(craft))return;undo.push(before);if(undo.length>70)undo.shift();redo=[];remember();updatePreview();updateMeta();updateSelection();if(category==='stickers')renderStickerControls();if(adjusting)renderAdjustments();if(message)say(message)}
function renderCraft(c,options={}){return drawWorkshopCraft(c,{...options,selectedCategory:category,selectedSticker})}
function constrain(s,c=craft){return constrainWorkshopSticker(s,c)}

function updatePreview(){$('#drawing').innerHTML=renderCraft(craft);$('#drawing').classList.toggle('flight-scale',flightScale);$('#scale-button').setAttribute('aria-pressed',String(flightScale));$('#scale-button').innerHTML=flightScale?'Close up <span aria-hidden="true">↙</span>':'Flight scale <span aria-hidden="true">↗</span>';$('#preview-hint').textContent=flightScale?'Illustrative size · no flight physics':category==='stickers'?'Drag the selected sticker on the surface':'Tap a part to explore it';$('#design-caption').textContent=craft.base==='car'?'Car concept · Earth Lander only':craft.base==='eagle'?'Eagle concept · original game model unchanged':'MODULAR DESIGN · COSMETIC PARTS'}
function updateMeta(){$('#craft-name').textContent=craft.name;$('#saved-state').textContent=dirty()?'● Unsaved changes':'✓ Saved design';$('#saved-state').classList.toggle('dirty',dirty());for(const button of [$('#save-button'),$('#footer-save-button')])button.textContent=dirty()?'Save craft':'Saved';$('#undo-button').disabled=!undo.length;$('#redo-button').disabled=!redo.length}
function currentOption(){return CATALOG[category]?.find(o=>o.id===craft[category])}
function updateSelection(){for(const b of $('#choices').querySelectorAll('[data-option]'))b.setAttribute('aria-pressed',String(category==='stickers'?false:category==='builds'?craft.base===b.dataset.option:craft[category]===b.dataset.option));$('#selection-label').textContent=category==='stickers'?`${craft.stickers.length} of ${MAX_STICKERS} stickers · Cabin / body`:category==='builds'?'Starting points, ready to remix':(category==='palette'&&Object.keys(craft.details.colors).length?'Custom paint · '+(currentOption()?.name||''):currentOption()?.name||'');$('#pin-button').setAttribute('aria-pressed',String(pins.has(category)));$('#pin-button').textContent=pins.has(category)?'Pinned ●':'Pin';$('#pin-button').hidden=['stickers','builds'].includes(category);$('#shuffle-button').hidden=category==='stickers';$('#adjust-button').hidden=category==='builds';$('#adjust-button').setAttribute('aria-pressed',String(adjusting));$('#adjust-button').textContent=adjusting?'← Choices':category==='palette'?'Custom paint':'Adjust';$('#save-button').disabled=false;}
function categoryIcon(path){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}" stroke-linejoin="round" stroke-linecap="round"/></svg>`}
function renderCategories(){$('#categories').innerHTML=PARTS.map(([id,label,path])=>`<button class="category" data-category="${id}" aria-pressed="${id===category}">${categoryIcon(path)}${label}</button>`).join('')}
function setCategory(id){category=id;filter='All';adjusting=false;renderCategories();renderShelf();updatePreview();updateSelection();if(category==='stickers')say('Pick a sticker. Drag it directly on the body.');else say(INFO[id][1])}
function choicePreview(o){if(category==='palette')return `<span class="choice-color" style="background:linear-gradient(135deg,${o.secondary} 0 28%,${o.primary} 28% 76%,${o.dark} 76%)"></span>`;if(category==='stickers')return `<span class="choice-glyph">${o.glyph}</span>`;const c=category==='builds'?build(o.id):{...craft,[category]:o.id};return renderCraft(c,{part:category==='builds'?null:category==='flame'?'flame':category,thumb:true})}
function renderShelf(){const box=$('#choices');$('#category-title').textContent=INFO[category][0];$('#category-subtitle').textContent=INFO[category][1];$('.console').classList.toggle('sticker-mode',category==='stickers');const filtered=['cabin','body','legs','builds'].includes(category);$('#filters').innerHTML=(filtered?['All','Space','Oddities']:[category==='palette'?'Coordinated':category==='flame'?'Cosmetic only':'Compatible']).map(v=>`<button data-filter="${v}" aria-pressed="${v===filter||!filtered}" ${!filtered?'disabled':''}>${v}</button>`).join('');const options=CATALOG[category].filter(o=>!filtered||filter==='All'||o.family===filter);box.setAttribute('aria-label',INFO[category][0]+' choices');box.innerHTML=options.map(o=>`<button class="choice" data-option="${o.id}" aria-label="${escape(o.name)}" aria-pressed="false" ${category==='stickers'&&craft.stickers.length>=MAX_STICKERS?'disabled':''}>${choicePreview(o)}<span class="choice-label">${escape(o.name)}</span>${category==='cabin'||category==='builds'?`<span class="choice-info">${o.family==='Oddities'?'A little unexpected':'Flight hardware'}</span>`:''}</button>`).join('');box.scrollLeft=0;box.scrollTop=0;$('#choice-count').textContent=options.length+' choices';renderStickerControls();updateSelection();revealSelected();renderAdjustments()}
function selectOption(id){const o=CATALOG[category].find(o=>o.id===id);if(!o)return;if(category==='stickers'){if(craft.stickers.length>=MAX_STICKERS)return;say('');mutate(()=>{craft.stickers.push({kind:'emoji',part:'body',color:'#f3e6c6',flip:false,glyph:o.glyph,x:0,y:33,size:22,rot:0});selectedSticker=craft.stickers.length-1;constrain(craft.stickers[selectedSticker])},`${o.name} added. Drag it on the body.`);$('#choices').querySelectorAll('button').forEach(b=>b.disabled=craft.stickers.length>=MAX_STICKERS);return}if(category==='builds'){mutate(()=>{const next=build(id);craft={...next,id:craft.id,name:craft.name,stickers:clone(craft.stickers)};craft.stickers.forEach(s=>constrain(s));selectedSticker=-1},o.name+' fitted. Make it yours.');renderShelf();return}mutate(()=>{craft[category]=id;if(category==='palette')craft.details.colors={};if(category==='flame')craft.details.flameColor='';if(!['palette','flame'].includes(category))craft.base='custom';if(['body','cabin'].includes(category))craft.stickers.forEach(s=>{if(s.part==='cabin'&&!cabinSurface(craft)){s.part='body';s.y=30}constrain(s)})},o.name+' fitted.');}
function renderStickerControls(){const el=$('#sticker-controls');el.hidden=category!=='stickers';if(category!=='stickers')return;const s=craft.stickers[selectedSticker];el.innerHTML=craft.stickers.length?`<select id="sticker-select" aria-label="Selected sticker"><option value="-1">Select</option>${craft.stickers.map((s,i)=>`<option value="${i}" ${i===selectedSticker?'selected':''}>${s.glyph} ${i+1}</option>`).join('')}</select>${s?`<label>Size<input id="sticker-size" aria-label="Sticker size" type="range" min="8" max="36" value="${s.size}"></label><label>Turn<input id="sticker-turn" aria-label="Sticker rotation" type="range" min="-180" max="180" value="${s.rot}"></label><button id="sticker-delete" aria-label="Delete selected sticker">Delete</button>`:'<p class="sticker-note">Tap a sticker to adjust it.</p>'}`:'<p class="sticker-note">Up to 12 stickers. Adjust adds lettering and cabin placement.</p>';if($('#sticker-select'))$('#sticker-select').onchange=e=>{selectedSticker=Number(e.target.value);updatePreview();renderStickerControls()};if(s){for(const [id,key] of [['#sticker-size','size'],['#sticker-turn','rot']])$(id).oninput=e=>{const value=Number(e.target.value),before=clone(craft);craft.stickers[selectedSticker][key]=value;constrain(craft.stickers[selectedSticker]);if(!e.target.dataset.started){undo.push(before);redo=[];e.target.dataset.started='yes'}remember();updatePreview();updateMeta()};for(const input of el.querySelectorAll('input[type=range]'))input.onchange=()=>delete input.dataset.started;$('#sticker-delete').onclick=()=>{mutate(()=>{craft.stickers.splice(selectedSticker,1);selectedSticker=Math.min(selectedSticker,craft.stickers.length-1)},'Sticker removed.');$('#choices').querySelectorAll('button').forEach(b=>b.disabled=false)}}}
function save(){const next=clone(collection),index=next.crafts.findIndex(c=>c.id===craft.id);if(index<0)next.crafts.push(clone(craft));else next.crafts[index]=clone(craft);next.selected=craft.id;if(store(next)){baseline=JSON.stringify(craft);clearDraft();updateMeta();say('Saved to My Craft. All yours.');return true}return false}
function historyStep(direction){const from=direction==='undo'?undo:redo,to=direction==='undo'?redo:undo;if(!from.length)return;to.push(clone(craft));craft=from.pop();selectedSticker=-1;remember();updatePreview();updateMeta();renderShelf();say(direction==='undo'?'Undone. Keep exploring.':'Restored.')}
function randomItem(items,current){const pool=items.filter(o=>o.id!==current);return pool[Math.floor(Math.random()*pool.length)]||items[0]}
function revealSelected(){const box=$('#choices'),selected=box.querySelector('[aria-pressed="true"]');if(!selected)return;const r=selected.getBoundingClientRect(),b=box.getBoundingClientRect();if(box.scrollWidth>box.clientWidth)box.scrollLeft+=r.left-b.left-(box.clientWidth-r.width)/2;else if(r.bottom>b.bottom||r.top<b.top)box.scrollTop+=r.top-b.top-(box.clientHeight-r.height)/2}
function shufflePart(){const o=randomItem(CATALOG[category],craft[category]);selectOption(o.id);revealSelected()}
function surprise(){mutate(()=>{for(const key of ['cabin','body','legs','engine','palette','flame'])if(!pins.has(key))craft[key]=randomItem(CATALOG[key],craft[key]).id;craft.base='custom';craft.stickers.forEach(s=>constrain(s))},pins.size?'A new mix. Pinned parts kept.':'Something unexpected. Make it yours.');renderShelf()}
function openDialog(html){dialog.innerHTML=html;if(!dialog.open)dialog.showModal()}
function closeDialog(){dialog.close()}
function guard(next){if(!dirty()){next();return}openDialog('<span class="eyebrow">BEFORE YOU GO</span><h2>Keep this version?</h2><p>Your last saved design is safe. Save your changes, or leave them behind.</p><div class="dialog-actions"><button id="guard-save" class="primary">Save & continue</button><button id="guard-discard">Discard changes</button><button data-close>Keep building</button></div>');$('#guard-save').onclick=()=>{if(save()){closeDialog();next()}};$('#guard-discard').onclick=()=>{craft=normalize(JSON.parse(baseline));undo=[];redo=[];clearDraft();updatePreview();updateMeta();renderShelf();closeDialog();next()}}
function rename(){openDialog(`<span class="eyebrow">MAKE IT YOURS</span><h2>A name for your craft</h2><form id="rename-form"><label for="new-name">Craft name</label><input id="new-name" maxlength="32" value="${escape(craft.name)}" autocomplete="off"><div class="dialog-actions"><button class="primary" type="submit">Use this name</button><button type="button" data-close>Cancel</button></div></form>`);$('#rename-form').onsubmit=e=>{e.preventDefault();const name=$('#new-name').value.trim()||'Untitled craft';mutate(()=>{craft.name=name},'A good name. Save when you’re ready.');closeDialog()};$('#new-name').focus();$('#new-name').select()}
function openCraft(id){const found=collection.crafts.find(c=>c.id===id);if(!found)return;craft=clone(found);baseline=JSON.stringify(craft);selectedSticker=-1;undo=[];redo=[];pins.clear();flightScale=false;clearDraft();setCategory('cabin');updateMeta();closeDialog()}
function uniqueName(name){let i=2;while(collection.crafts.some(c=>c.name===`${name.slice(0,28)} ${i}`))i++;return `${name.slice(0,28)} ${i}`}
function fleet(){openDialog(`<div class="dialog-head"><div><span class="eyebrow">YOUR OWN LITTLE SPACE PROGRAM</span><h2>My Craft</h2></div><button data-close aria-label="Close My Craft">✕</button></div><p>Pick a craft to keep building. These designs live only in this prototype.</p><div class="fleet-grid">${collection.crafts.map(c=>`<article class="fleet-card ${c.id===craft.id?'selected':''}">${renderCraft(c,{thumb:true})}<h3>${escape(c.name)}</h3><div class="card-actions"><button data-edit="${escape(c.id)}" class="primary">Build</button><button data-copy="${escape(c.id)}">Duplicate</button><button data-rename="${escape(c.id)}">Rename</button><button data-delete="${escape(c.id)}" aria-label="Delete ${escape(c.name)}">Delete</button></div></article>`).join('')}</div><div class="fleet-footer"><button id="new-craft" class="primary">＋ New craft</button><a class="astra-return" id="astra-return" href="../../" target="_top">← Back to ASTRA</a></div><p class="empty-note">Concept artwork · Cosmetic choices · No game handling or game saves changed</p>`);$('#new-craft').onclick=newCraft;$('#astra-return').onclick=e=>{if(dirty()){e.preventDefault();guard(()=>window.top.location.href='../../')}};dialog.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openCraft(b.dataset.edit));dialog.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>{const next=clone(collection),c=clone(next.crafts.find(c=>c.id===b.dataset.copy));c.id=uid();c.name=uniqueName(c.name);next.crafts.push(c);if(store(next)){say('Copy saved to My Craft.');fleet()}});dialog.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>{const id=b.dataset.rename,c=collection.crafts.find(c=>c.id===id);openDialog(`<h2>Rename craft</h2><form id="fleet-rename"><label for="fleet-name">Craft name</label><input id="fleet-name" maxlength="32" value="${escape(c.name)}"><div class="dialog-actions"><button type="submit" class="primary">Save name</button><button type="button" id="rename-back">Cancel</button></div></form>`);$('#rename-back').onclick=fleet;$('#fleet-rename').onsubmit=e=>{e.preventDefault();const next=clone(collection),name=$('#fleet-name').value.trim()||c.name;next.crafts.find(c=>c.id===id).name=name;if(store(next)){if(craft.id===id){craft.name=name;baseline=JSON.stringify(craft);updateMeta()}fleet()}}});dialog.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const id=b.dataset.delete,c=collection.crafts.find(c=>c.id===id);openDialog(`<h2>Delete ${escape(c.name)}?</h2><p>${collection.crafts.length===1?'Keep at least one craft in your collection.':'This removes this saved prototype design. Your game craft are unaffected.'}</p><div class="dialog-actions"><button id="confirm-delete" class="danger" ${collection.crafts.length===1?'disabled':''}>Delete craft</button><button id="keep-craft">Keep craft</button></div>`);$('#keep-craft').onclick=fleet;$('#confirm-delete').onclick=()=>{const next=clone(collection);next.crafts=next.crafts.filter(c=>c.id!==id);if(next.selected===id)next.selected=next.crafts[0].id;if(store(next)){if(craft.id===id){openCraft(next.selected)}fleet()}}})}
function newCraft(){openDialog(`<div class="dialog-head"><div><span class="eyebrow">WHAT WILL YOU BUILD?</span><h2>A new beginning</h2></div><button data-close aria-label="Close">✕</button></div><p>A starting point, not a commitment. Every part is yours to change.</p><div class="new-options"><button data-start="explorer"><span class="symbol">◇</span><b>Spacecraft</b><span>Start with a proper little lander.</span></button><button data-start="visitor"><span class="symbol">👽</span><b>Character</b><span>A personality with landing gear.</span></button><button data-start="random"><span class="symbol">✧</span><b>Surprise me</b><span>See where a strange combination takes you.</span></button></div><div class="dialog-actions"><button id="new-back">← My Craft</button></div>`);$('#new-back').onclick=fleet;dialog.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{craft=build(b.dataset.start==='random'?'explorer':b.dataset.start);craft.name='Untitled craft';baseline=JSON.stringify({...craft,id:'not-saved'});undo=[];redo=[];selectedSticker=-1;flightScale=false;pins.clear();if(b.dataset.start==='random')for(const key of ['cabin','body','legs','engine','palette','flame'])craft[key]=randomItem(CATALOG[key]).id;closeDialog();remember();setCategory('cabin');updateMeta();say('Your new craft. Change anything.');})}
let drag=null;
$('#drawing').addEventListener('pointerdown',e=>{const sticker=e.target.closest('[data-sticker]');if(sticker){e.preventDefault();const i=Number(sticker.dataset.sticker);if(category!=='stickers')setCategory('stickers');selectedSticker=i;updatePreview();renderStickerControls();drag={pointer:e.pointerId,before:clone(craft),moved:false};$('#drawing').setPointerCapture(e.pointerId);return}const part=e.target.closest('[data-part]');if(part)setCategory(part.dataset.part)});
$('#drawing').addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const svg=$('#drawing svg'),point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),s=craft.stickers[selectedSticker];const d=craft.details;s.x=point.x/(s.part==='cabin'?d.cabinW:d.bodyW);s.y=s.part==='cabin'?(point.y+14)/d.cabinH-14:point.y;constrain(s);drag.moved=true;updatePreview()});
function endDrag(){if(!drag)return;if(drag.moved&&JSON.stringify(drag.before)!==JSON.stringify(craft)){undo.push(drag.before);redo=[];remember();updateMeta();say('Sticker placed.')}drag=null}
$('#drawing').addEventListener('pointerup',endDrag);$('#drawing').addEventListener('pointercancel',endDrag);
$('#categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b)setCategory(b.dataset.category)};
$('#choices').onclick=e=>{const b=e.target.closest('[data-option]');if(b&&!b.disabled)selectOption(b.dataset.option)};
$('#filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b&&!b.disabled){filter=b.dataset.filter;renderShelf()}};
$('#previous').onclick=()=>$('#choices').scrollBy({left:-220,behavior:'smooth'});$('#next').onclick=()=>$('#choices').scrollBy({left:220,behavior:'smooth'});
$('#pin-button').onclick=()=>{if(pins.has(category))pins.delete(category);else pins.add(category);updateSelection();say(pins.has(category)?'This part stays when you use Surprise me.':'Part unpinned.')};
$('#shuffle-button').onclick=shufflePart;$('#surprise-button').onclick=surprise;$('#undo-button').onclick=()=>historyStep('undo');$('#redo-button').onclick=()=>historyStep('redo');$('#save-button').onclick=()=>{if(craft.name==='Untitled craft'){rename();const form=$('#rename-form'),original=form.onsubmit;form.onsubmit=e=>{original(e);save()}}else save()};$('#footer-save-button').onclick=()=>$('#save-button').click();$('#rename-button').onclick=rename;$('#fleet-button').onclick=()=>guard(fleet);$('#scale-button').onclick=()=>{flightScale=!flightScale;updatePreview()};
dialog.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeDialog()});
window.addEventListener('keydown',e=>{if(dialog.open||e.target.closest('input,select,textarea'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();historyStep(e.shiftKey?'redo':'undo')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('#save-button').click()}});
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue=''}});
function detailRange(label,key,min,max){const value=Math.round(craft.details[key]*100);return `<label class="range-setting"><span>${label}<output>${value}%</output></span><input type="range" data-detail="${key}" min="${min}" max="${max}" value="${value}" aria-label="${label}"></label>`}
function colorSetting(label,key,value){return `<label class="color-setting"><input type="color" data-color="${key}" value="${value}" aria-label="${label}"><span>${label}</span></label>`}
function liveAdjust(input,fn){if(!input.dataset.editing){undo.push(clone(craft));redo=[];input.dataset.editing='yes'}fn();craft.stickers.forEach(s=>constrain(s));remember();updatePreview();updateMeta();updateSelection();const output=input.closest('label')?.querySelector('output');if(output)output.textContent=input.value+'%';say('Updated. Your craft, your way.')}
function renderAdjustments(){const el=$('#adjustments');el.hidden=!adjusting;$('#choices').hidden=adjusting;$('.filter-row').hidden=adjusting;$('.console').classList.toggle('adjusting',adjusting);$('#sticker-controls').hidden=category!=='stickers'||adjusting;if(!adjusting)return;const d=craft.details,p=palette(craft),s=craft.stickers[selectedSticker];let content='';
 if(category==='palette')content=`<p class="adjust-note">Seven independent colors. Presets are always one click away.</p><div class="color-grid">${colorSetting('Body paint','body',p.primary)}${colorSetting('Cabin paint','cabin',p.secondary)}${colorSetting('Trim paint','trim',p.dark)}${colorSetting('Glass color','glass',p.glass)}${colorSetting('Leg paint','legs',p.hardware)}${colorSetting('Engine paint','engine',p.engine)}${colorSetting('Foot trim','feet',p.foot)}</div>`;
 if(category==='cabin')content=`<div class="color-grid">${colorSetting('Cabin paint','cabin',p.secondary)}${colorSetting('Glass color','glass',p.glass)}</div>${detailRange('Cabin width','cabinW',80,115)}${detailRange('Cabin height','cabinH',80,110)}<p class="adjust-note">The mounting point stays attached to the body.</p>`;
 if(category==='body')content=`<div class="color-grid">${colorSetting('Body paint','body',p.primary)}${colorSetting('Trim paint','trim',p.dark)}</div>${detailRange('Body width','bodyW',90,112)}<span class="setting-label">Surface pattern</span><div class="pattern-choices">${['none','stripes','checkers','panels','dots'].map(v=>`<button data-pattern="${v}" aria-pressed="${d.pattern===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div>`;
 if(category==='legs')content=`<div class="color-grid">${colorSetting('Leg paint','legs',p.hardware)}${colorSetting('Foot trim','feet',p.foot)}</div><p class="adjust-note">Custom paint for the hardware. Geometry follows the chosen landing gear.</p>`;
 if(category==='engine')content=`<div class="color-grid">${colorSetting('Engine paint','engine',p.engine)}</div>${detailRange('Nozzle width','engineW',80,112)}<p class="adjust-note">Appearance only. Thrust and fuel performance do not change.</p>`;
 if(category==='flame')content=`<span class="setting-label">Flame shape</span><div class="pattern-choices">${['plume','jet','fork','bubbles','sparks'].map(v=>`<button data-flame-shape="${v}" aria-pressed="${d.flameShape===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div>${detailRange('Flame length','flameLength',50,115)}<div class="color-grid">${colorSetting('Flame color','flameColor',d.flameColor||CATALOG.flame.find(o=>o.id===craft.flame).color)}${colorSetting('Flame core','flameCore',d.flameCore)}</div>${craft.flame==='off'?'<p class="adjust-note">Choose a flame color to turn the engine preview on.</p>':''}`;
 if(category==='stickers')content=`<div class="lettering-entry"><label for="lettering">Add lettering</label><div><input id="lettering" maxlength="8" placeholder="ASTRA" autocomplete="off" aria-label="Lettering text"><button id="add-lettering" ${craft.stickers.length>=MAX_STICKERS?'disabled':''}>Add lettering</button></div></div>${craft.stickers.length?`<label class="surface-label">Selected sticker<select id="detail-sticker-select" aria-label="Sticker to customize"><option value="-1">Choose a sticker</option>${craft.stickers.map((x,i)=>`<option value="${i}" ${i===selectedSticker?'selected':''}>${i+1} · ${escape(x.glyph)}</option>`).join('')}</select></label>`:''}${s?`<label class="surface-label">Attached to<select id="sticker-surface" aria-label="Sticker surface"><option value="body" ${s.part!=='cabin'?'selected':''}>Body</option><option value="cabin" ${s.part==='cabin'?'selected':''} ${!cabinSurface(craft)?'disabled':''}>Cabin${!cabinSurface(craft)?' · choose a solid cabin':''}</option></select></label><div class="detail-sticker-sliders"><label>Size<input id="detail-sticker-size" type="range" min="8" max="36" value="${s.size}" aria-label="Sticker size adjustment"></label><label>Rotation<input id="detail-sticker-turn" type="range" min="-180" max="180" value="${s.rot}" aria-label="Sticker rotation adjustment"></label></div>${s.kind==='text'?`<div class="color-grid">${colorSetting('Lettering color','lettering',s.color||'#f3e6c6')}</div>`:''}<div class="pattern-choices"><button id="copy-sticker" ${craft.stickers.length>=MAX_STICKERS?'disabled':''}>Duplicate</button><button id="flip-sticker" aria-pressed="${!!s.flip}">Mirror</button><button id="detail-sticker-delete">Delete sticker</button></div>`:'<p class="adjust-note">Add lettering here, or return to Choices for 36 stickers. Then select a sticker to position, resize, rotate, or mirror it.</p>'}`;
 el.innerHTML=content+(category!=='stickers'?'<button id="reset-adjustments" class="reset-adjustments">Reset these adjustments</button>':'');
 el.querySelectorAll('[data-detail]').forEach(input=>{input.oninput=()=>liveAdjust(input,()=>{craft.details[input.dataset.detail]=Number(input.value)/100});input.onchange=()=>delete input.dataset.editing});
 el.querySelectorAll('[data-color]').forEach(input=>{input.oninput=()=>liveAdjust(input,()=>{const key=input.dataset.color;if(key==='lettering'&&s)s.color=input.value;else if(key==='flameColor'||key==='flameCore'){d[key]=input.value;if(craft.flame==='off')craft.flame='ice'}else d.colors[key]=input.value});input.onchange=()=>delete input.dataset.editing});
 el.querySelectorAll('[data-pattern]').forEach(b=>b.onclick=()=>mutate(()=>{d.pattern=b.dataset.pattern},'Surface pattern updated.'));
 el.querySelectorAll('[data-flame-shape]').forEach(b=>b.onclick=()=>mutate(()=>{d.flameShape=b.dataset.flameShape;if(craft.flame==='off')craft.flame='ice'},'Flame shape updated.'));
 if($('#reset-adjustments'))$('#reset-adjustments').onclick=()=>mutate(()=>{const defaults=defaultDetails();const colorKeys={palette:['body','cabin','trim','glass','legs','engine','feet'],cabin:['cabin','glass'],body:['body','trim'],legs:['legs','feet'],engine:['engine'],flame:[]}[category];for(const key of colorKeys)delete d.colors[key];const keys={palette:[],cabin:['cabinW','cabinH'],body:['bodyW','pattern'],legs:[],engine:['engineW'],flame:['flameLength','flameShape','flameColor','flameCore']}[category];for(const key of keys)d[key]=defaults[key]},'These adjustments reset.');
 if($('#add-lettering'))$('#add-lettering').onclick=()=>{const glyph=$('#lettering').value.trim().slice(0,8)||'ASTRA';mutate(()=>{craft.stickers.push({kind:'text',part:'body',glyph,color:'#f3e6c6',flip:false,x:0,y:34,size:18,rot:0});selectedSticker=craft.stickers.length-1;constrain(craft.stickers[selectedSticker])},'Lettering added. Drag it on the craft.')};
 if($('#detail-sticker-select'))$('#detail-sticker-select').onchange=e=>{selectedSticker=Number(e.target.value);updatePreview();renderAdjustments()};
 if(s){$('#sticker-surface').onchange=e=>mutate(()=>{s.part=e.target.value;s.x=0;s.y=s.part==='cabin'?-46:33;constrain(s)},'Sticker attached to '+$('#sticker-surface').value+'.');for(const [id,key]of [['#detail-sticker-size','size'],['#detail-sticker-turn','rot']]){const input=$(id);input.oninput=()=>liveAdjust(input,()=>{s[key]=Number(input.value)});input.onchange=()=>delete input.dataset.editing}$('#copy-sticker').onclick=()=>mutate(()=>{const next={...s,x:s.x+6,y:s.y+3};constrain(next);craft.stickers.push(next);selectedSticker=craft.stickers.length-1},'Sticker duplicated.');$('#flip-sticker').onclick=()=>mutate(()=>{s.flip=!s.flip},'Sticker mirrored.');$('#detail-sticker-delete').onclick=()=>mutate(()=>{craft.stickers.splice(selectedSticker,1);selectedSticker=Math.min(selectedSticker,craft.stickers.length-1)},'Sticker removed.')}
}
$('#adjust-button').onclick=()=>{adjusting=!adjusting;if(!adjusting)renderShelf();updateSelection();renderAdjustments();say(adjusting?'Fine-tune it. Your craft stays in view.':'Choose another part.')};

renderCategories();renderShelf();updatePreview();updateMeta();
if(storageIssue)say(storageIssue);else if(legacyImported)say('Your earlier prototype fleet is here, adapted to this kit.');else say('Pick a cabin. See what happens.');
try{const recovered=JSON.parse(localStorage.getItem(DRAFT_KEY));if(recovered?.craft?.id&&typeof recovered.baseline==='string'){JSON.parse(recovered.baseline);openDialog('<span class="eyebrow">WELCOME BACK</span><h2>Your workbench is waiting.</h2><p>There’s a design in progress. Carry on where you left off?</p><div class="dialog-actions"><button id="resume-draft" class="primary">Resume building</button><button id="discard-draft">Discard draft</button></div>');$('#resume-draft').onclick=()=>{craft=normalize(recovered.craft);baseline=JSON.stringify(normalize(JSON.parse(recovered.baseline)));selectedSticker=-1;renderShelf();updatePreview();updateMeta();closeDialog();say('Right where you left it.')};$('#discard-draft').onclick=()=>{clearDraft();closeDialog()}}}catch{say('Could not recover the draft. Saved craft are still available.')}
